<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$d=json_input();$identity=trim((string)($d['identity']??''));$password=(string)($d['password']??'');$hash=hash('sha256',strtolower($identity));$r=db()->prepare('SELECT COUNT(*) FROM vendor_login_attempts WHERE (identity_hash=? OR ip_address=?) AND successful=0 AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$r->execute([$hash,client_ip()]);if((int)$r->fetchColumn()>=5)json_response(false,'Too many attempts',null,429);$s=db()->prepare("SELECT vu.*,v.status vendor_status FROM vendor_users vu JOIN vendors v ON v.id=vu.vendor_id WHERE (vu.username=? OR vu.email=?) LIMIT 1");$s->execute([$identity,$identity]);$u=$s->fetch();$ok=$u&&$u['status']==='ACTIVE'&&$u['vendor_status']==='ACTIVE'&&password_verify($password,$u['password_hash']);db()->prepare('INSERT INTO vendor_login_attempts(identity_hash,ip_address,successful) VALUES(?,?,?)')->execute([$hash,client_ip(),$ok?1:0]);if(!$ok)json_response(false,'Invalid credentials',null,401);$token=bin2hex(random_bytes(32));db()->prepare('INSERT INTO vendor_sessions(vendor_user_id,token_hash,ip_address,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 8 HOUR))')->execute([$u['id'],hash('sha256',$token),client_ip()]);json_response(true,'Vendor login successful',['token'=>$token,'expires_in'=>28800]);
